  const text = document.body.innerText;
  const versions = [...document.querySelectorAll('button')].map(b => b.innerText).filter(t => /版本\s*\d/.test(t));
  const buildLinks = [...document.querySelectorAll('a')].filter(a => /构建版本/.test(a.innerText) || /\d{7,}/.test(a.getAttribute('aria-description') || '') || /\d{7,}/.test(a.textContent || ''));
  const buildNums = [...new Set(buildLinks.map(a => {
    const m = (a.textContent + ' ' + (a.getAttribute('aria-description')||'')).match(/\d{4,}/g);
    return m ? m[m.length-1] : null;
  }).filter(Boolean))];
  const uploadSection = document.body.innerText.includes('构建版本上传');
  return {
    title: document.title,
    url: location.href,
    appMenu: document.querySelector('[aria-label*="App"]')?.innerText || null,
    versions,
    buildNums,
    snippet: text.slice(text.indexOf('iOS 构建版本'), text.indexOf('iOS 构建版本') + 2500)
  };
}

async () => {
  const clickText = (t) => {
    const el = [...document.querySelectorAll('button, a, [role=button]')].find(e => (e.innerText || '').trim().includes(t));
    if (el) { el.click(); return true; }
    return false;
  };
  const moreClicked = clickText('查看更多');
  await new Promise(r => setTimeout(r, 1500));
  const versionsToOpen = ['版本 1.2.2','版本 1.2.1','版本 1.2.0','版本 1.1.71'];
  for (const v of versionsToOpen) {
    clickText(v);
    await new Promise(r => setTimeout(r, 400));
  }
  await new Promise(r => setTimeout(r, 1500));
  const text = document.body.innerText;
  const uploads = [...text.matchAll(/版本\s*([0-9.]+)[\s\S]{0,40}构建版本[\s\S]{0,20}\(?([0-9.]+)\)?/g)].map(m => ({version:m[1], build:m[2]}));
  const builds = [...text.matchAll(/构建版本\s*\n?\s*([0-9.]+)/g)].map(m => m[1]);
  return {
    moreClicked,
    uniqueBuilds: [...new Set([...uploads.map(u=>u.build), ...builds])],
    uploads,
    snippetStart: text.includes('查看更多') ? 'still has 查看更多' : 'no 查看更多',
    uploadSnippet: text.slice(text.indexOf('构建版本上传'), text.indexOf('构建版本上传') + 3500)
  };
}

